// Traverse all elements with nested loops
int[][] matrix = {{1, 2}, {3, 4}, {5, 6}};

for (int i = 0; i < matrix.length; i++) {
    for (int j = 0; j < matrix[i].length; j++) {
        System.out.printf("%4d", matrix[i][j]);
    }
    System.out.println();
}

// Sum all elements
int total = 0;
for (int[] row : matrix)
    for (int val : row)
        total += val;
System.out.println("Sum: " + total);  // 21
